LOG_HEAD = LOG_END = "*" * 8


class GenericRU(object):
    @staticmethod
    def remove_ap_rus(ru_infos, gnb_index=0, vdu_index=0):
        real_ru_sn_list = get_all_ru_sn_from_tl(
            gnb_index=gnb_index, vdu_index=vdu_index
        )
        for ru_info in ru_infos:
            if ru_info["serial_number"] not in real_ru_sn_list:
                ru_infos.remove(ru_info)
        return ru_infos

    def get_ru_info_list_by_ru_type(self, ru_infos_list, ru_type):
        ru_info_list_new = []
        for ru_info in ru_infos_list:
            if ru_info["type"] == ru_type:
                ru_info_list_new.append(ru_info)
        return ru_info_list_new

    def get_atten_info_by_ru_model(self, model):
        attenuator_info = get_attenuator_info_from_tl()
        if attenuator_info:
            return attenuator_info.get(model)

    def get_ru_infos(self, ru_infos, serviceuser_new_pwd=None):
        ru_info_list = []
        for ru_info in ru_infos:
            model = ru_info["product_name"]
            sn = ru_info["serial_number"]
            cell_ids = ru_info["cell_ids"]
            ru_info = self.get_ru_infos_by_ru_model(model)
            if serviceuser_new_pwd is not None and ru_info['username'] == 'serviceuser':
                ru_info['password'] = serviceuser_new_pwd
            atten = self.get_atten_info_by_ru_model(model)
            if atten:
                ru_info["atten"] = atten
            ru_info["model"] = model
            ru_info["sn"] = sn
            ru_info["cell_ids"] = cell_ids
            ru_info_list.append(ru_info)
        return ru_info_list

    def get_ru_id_list(self, ru_infos):
        ru_id_list = []
        for ru_info in ru_infos:
            id = ru_info["id"]
            ru_id_list.append(id)
        return ru_id_list

    def ru_status_should_be_as_expected(
        self, ru_id, ru_infos, log_level="DEBUG", **kwargs
    ):
        unexpected = False
        for ru_info in ru_infos:
            if ru_id == ru_info["id"]:
                for key, value in kwargs.items():
                    try:
                        if ru_info[key] != value:
                            raise AssertionError(
                                "{log_head} The {state} of RMOD-{ru_id} is {status} {log_end}".format(
                                    log_head=LOG_HEAD,
                                    state=key,
                                    ru_id=ru_info["id"],
                                    status=ru_info[key],
                                    log_end=LOG_END,
                                )
                            )
                    except AssertionError as e:
                        if log_level == "ERROR":
                            logger.error(str(e))
                        else:
                            logger.debug(str(e))
                        unexpected = True
                        continue
        return unexpected

    def get_ru_infos_by_ru_model(self, ru_model):
        all_ru_infos = global_variables.get_all_RF_infos()
        for ru_info in all_ru_infos:
            if ru_model in ru_info["model"]:
                return ru_info

    def get_cell_band_mapping(self, cell_status, cell_technology=None):
        cell_band_mapping = {}
        for cell in cell_status:
            if cell_technology:
                if cell["technology"] != cell_technology:
                    continue
            band = re.search("\\d+", cell["band"])
            cell_band_mapping[cell["id"]] = band.group()
        return cell_band_mapping

    def replace_sn_with_mac(self, rf_info_list, sn_mac_dict):
        for sn in sn_mac_dict:
            for ru_info in rf_info_list:
                if ru_info["sn"] == sn:
                    ru_info["sn"] = sn_mac_dict[sn]
        return rf_info_list


class TDDRUOpe(SSHConnExec):
    def get_rf_ip(self, rf_info_list, alias="default"):
        command = "ls /var/log/kea-leasesdb | grep kea-leases4.csv"
        output = SSHConnExec.execute_normal_cmd(self, base_command=command, alias=alias)
        file_list = output.split("\n")
        logger.console(file_list)
        results = []
        for ru_info in rf_info_list:
            sn = ru_info["sn"]
            if ":" in sn:
                sn_info = sn
            else:
                sn_info = ":".join([hex(ord(x)).lstrip("0x") for x in sn])
            total_content = ""
            file_title_info = None
            for file in file_list:
                file = file.replace("\r", "")
                command = "cat /var/log/kea-leasesdb/%s | grep '%s' " % (file, sn_info)
                # command = "cat /var/log/kea-leasesdb/%s | grep -i -E \"300|4000\" " % (file)
                content = SSHConnExec.execute_normal_cmd(
                    self, base_command=command, check_result=False, alias=alias
                )
                total_content = total_content + content
                file_title_info = SSHConnExec.execute_normal_cmd(
                    self,
                    base_command="cat /var/log/kea-leasesdb/%s | grep -m 1 address"
                    % file,
                    check_result=False,
                    alias=alias,
                )
            if not file_title_info:
                raise Exception("get title of file kea-leasesdb failed.")
            ru_info["ru_ip"] = self.get_ip_from_csv_txt(
                content=total_content, file_title_info=file_title_info
            )
            results.append(ru_info)
        return results

    def connect_to_ru_tdd(
        self,
        ru_ip,
        username,
        password,
        ru_local_ip,
        ru_prompt="Node\\d:~#",
        alias="default",
        need_login_local_ip=True,
        is_dc=0,
    ):
        logger.console("This is connect to ru tdd, is_dc value is {}".format(is_dc))
        if is_dc == 1:
            cmd = "ssh -B lo {username}@{ru_ip}".format(username=username, ru_ip=ru_ip)
            old_prompt = self.ssh_conn.get_prompt(alias=alias)
            new_prompt = "fingerprint"
            self.ssh_conn.set_prompt(prompt_str=new_prompt, alias=alias)
            self.ssh_conn.execute(command=cmd, check_result=False, alias=alias)
            new_prompt = "password:"
            self.ssh_conn.set_prompt(prompt_str=new_prompt, alias=alias)
            self.ssh_conn.execute(command="yes", check_result=False, alias=alias)
            new_prompt = old_prompt + "|\\$|" + ru_prompt + "|:~#"
            self.ssh_conn.set_prompt(prompt_str=new_prompt, alias=alias)
            logger.info(password)
            self.ssh_conn.execute(command=password, check_result=False, alias=alias)
        else:
            cmd = "ssh -o StrictHostKeyChecking=no {username}@{ru_ip}".format(
                username=username, ru_ip=ru_ip
            )
            logger.console(cmd)
            old_prompt = self.ssh_conn.get_prompt(alias=alias)
            new_prompt = "password:"
            self.ssh_conn.set_prompt(prompt_str=new_prompt, alias=alias)
            self.ssh_conn.execute(command=cmd, check_result=False, alias=alias)
            new_prompt = old_prompt + "|\\$|" + ru_prompt + "|:~#"
            self.ssh_conn.set_prompt(prompt_str=new_prompt, alias=alias)
            logger.info(password)
            self.ssh_conn.execute(command=password, check_result=False, alias=alias)
        if need_login_local_ip is True:
            cmd = "ssh {ru_local_ip}".format(ru_local_ip=ru_local_ip)
            self.ssh_conn.execute(command=cmd, check_result=False, alias=alias)
            time.sleep(1)
        return alias

    def connect_to_tdd_container(
        self, ns, alias="default", gnb_index=0, vdu_index=0, need_reconnect=True
    ):
        if need_reconnect:
            self.connect_to_vdu_cloud_hosting(
                using_tenant=True, alias=alias, gnb_index=gnb_index, vdu_index=vdu_index
            )
        self.connect_to_container(
            "oamfh", "oamfh", check_result=False, conn_alias=alias, namespace=ns
        )

    def collect_log_tdd(self, username, log_name, ru_prompt, alias="default"):
        old_prompt = self.ssh_conn.get_prompt(alias=alias)
        new_prompt = (
            old_prompt + "|root@made-Node1:/home/serviceuser#" + "/|%s#" % username
        )
        self.ssh_conn.set_prompt(new_prompt, alias=alias)
        self.ssh_conn.execute("sudo su", alias=alias, check_result=False)
        time.sleep(0.2)
        cmd = "log -a -z {}".format(log_name)
        self.ssh_conn.execute(command=cmd, alias=alias, check_result=False)
        time.sleep(3)

        self.ssh_conn.set_prompt(old_prompt + "|serviceuser@made-Node1:~#", alias=alias)
        self.ssh_conn.execute(command="exit", check_result=False, alias=alias)

        time.sleep(0.5)
        self.ssh_conn.set_prompt(old_prompt + "|" + ru_prompt, alias=alias)
        self.ssh_conn.execute(command="exit", check_result=False, alias=alias)
        time.sleep(0.5)
        return old_prompt

    def download_tdd_log_to_container(
        self, rf_local_ip, RF_ip, log_name, old_prompt, password, alias
    ):
        ru_path = "/var/tmp"
        cmd = "scp {}:/run/{} {}".format(rf_local_ip, log_name, ru_path)
        self.ssh_conn.execute(cmd, alias=alias, check_result=False)

        self.ssh_conn.set_prompt(old_prompt + "|bash-5.1$", alias=alias)
        self.ssh_conn.execute("exit", alias=alias, check_result=False)

        time.sleep(0.5)
        path_in_container = "/tmp"
        cp_cmd = "scp -o StrictHostKeyChecking=no serviceuser@{}:{}/{} {}".format(
            RF_ip, ru_path, log_name, path_in_container
        )
        self.ssh_conn.set_prompt(old_prompt + "|assword:", alias=alias)
        self.ssh_conn.execute(cp_cmd, alias=alias, check_result=False)

        self.ssh_conn.execute(password, alias=alias, check_result=False)
        time.sleep(1)
        return ru_path + "/" + log_name, path_in_container + "/" + log_name

    def delete_file_after_collect_tdd_log(
        self, delete_cmd1, delete_cmd2, password, alias
    ):
        self.ssh_conn.execute("exit", alias=alias, check_result=False)

        self.ssh_conn.execute(command=delete_cmd1, alias=alias, check_result=False)
        self.ssh_conn.execute(command=password, alias=alias, check_result=False)
        time.sleep(1)
        self.ssh_conn.execute(command=delete_cmd2, alias=alias, check_result=False)
        self.ssh_conn.execute(command=password, alias=alias, check_result=False)

    def check_power_tdd(self, att_index, alias="default"):
        cmd = "sudo dapd -pwr {index};".format(index=att_index)
        output = self.ssh_conn.execute(command=cmd, check_result=False, alias=alias)
        matches = re.search(r"TX=((-?\d+)(\.\d+).*FB=(-?\d+)(\.\d+))", output)
        if matches:
            logger.console(
                "att_{att_index}: {power}".format(
                    power=matches.group(), att_index=att_index
                )
            )
        else:
            logger.console("{output}".format(output=output))
            raise AssertionError(
                "No power detected on att_{att_index}".format(att_index=att_index)
            )

    def get_ip_from_csv_txt(self, content, file_title_info):
        content = content.strip()
        lines_info = content.split("\n")
        name_list = file_title_info.split(",")
        ip_index = -1
        time_index = -1
        for i in range(len(name_list)):
            if name_list[i] == "address" and ip_index == -1:
                ip_index = i
                continue
            if name_list[i] == "expire" and time_index == -1:
                time_index = i
                continue
        if ip_index == -1 or time_index == -1:
            raise Exception("need to adapt due to csv file changed.")
        _expire = 0
        for info in lines_info:
            split_info = info.split(",")
            expire = split_info[time_index]
            if int(expire) > int(_expire):
                _expire = expire
                ip = split_info[ip_index]
        return ip

    def _remove_repeat_item(self, mac_address, result):
        for r in result:
            if r["mac"] == mac_address:
                result.remove(r)
                return

    def _parse_sn(self, sn_info):
        sn_nums = sn_info.split(":")
        sn = ""
        for i in range(len(sn_nums) - 1, len(sn_nums) - 6, -1):
            sn = sn_nums[i][-1] + sn
        return sn

    def _check_repeat(self, result, results):
        for r in results:
            if r["mac"] == result["mac"]:
                if int(result["expire"]) > int(r["expire"]):
                    results.remove(r)
                    return 1  # need append
                else:
                    return 0
        return 1


class FDDRUOpe(SSHConnExec):
    def get_ru_ip(self, ru_infos, gnb_index, vdu_index, fhgw_index):
        alias = generic_utils.get_unique_id_string()
        SSHConnExec.ssh_connection_to_fhgw(
            self,
            gnb_index=gnb_index,
            vdu_index=vdu_index,
            fhgw_index=fhgw_index,
            alias=alias,
        )
        sn_list = []
        for ru_info in ru_infos:
            sn_list.append(ru_info["sn"])
        logger.info(sn_list)
        sn_index_dict = {}
        for i in range(20):
            sn = ""
            sn_number_command = "sudo redis-cli -n `expr $j + %d` get serialNum" % (
                i + 18
            )
            sn_number_out = SSHConnExec.execute_normal_cmd(
                self, base_command=sn_number_command, alias=alias
            )
            logger.debug(sn_number_out)
            if "nil" not in sn_number_out:
                sn = sn_number_out.split('"')[1]
                if sn in sn_list:
                    sn_list.remove(sn)
                    sn_index_dict[sn] = i
            if not sn_list:
                logger.debug("find all the rus")
                break
        logger.info(sn_index_dict)
        for sn in sn_index_dict:
            for ru_info in ru_infos:
                sn_number = ru_info["sn"]
                if sn == sn_number:
                    i = sn_index_dict[sn]
                    rf_ip_command = (
                        "sudo redis-cli -n `expr $j + %d` get RRH_IP_ADDR" % (i + 18)
                    )
                    rf_ip_out = SSHConnExec.execute_normal_cmd(
                        self, base_command=rf_ip_command, alias=alias
                    )
                    rf_ip = rf_ip_out.split('"')[1]
                    ru_info["rf_ip"] = rf_ip
        command = "docker ps | grep rup | awk '{print $1, $NF}'"
        output = SSHConnExec.execute_normal_cmd(self, base_command=command, alias=alias)
        pid_list = output.split("\n")
        pid_dict = self.get_pid_relationship(pid_list)
        logger.info(pid_list)
        SSHConnExec.disconnect_fhgw_ssh_conn(self, alias=alias)
        for ru_info in ru_infos:
            index_tmp = ru_info["rf_ip"].split(".")
            index = index_tmp[2]
            pid = pid_dict[index]
            ru_info["pid"] = pid
            ru_info["ruproxy_index"] = index
        return ru_infos

    def get_pid_relationship(self, pid_list):
        result = {}
        for pid_info in pid_list:
            if "ruproxy" in pid_info:
                tmps = pid_info.split(" ")
                result[tmps[1][8]] = tmps[0]
        return result

    def connect_to_ru_fdd(
        self,
        ru_info,
        gnb_index,
        vdu_index,
        fhgw_index,
        ru_prompt="Node\\d:~#",
        alias="default",
    ):
        SSHConnExec.ssh_connection_to_fhgw(
            self,
            gnb_index=gnb_index,
            vdu_index=vdu_index,
            fhgw_index=fhgw_index,
            alias=alias,
        )
        command = "docker ps | grep rup | awk '{print $1, $NF}'"
        SSHConnExec.execute_normal_cmd(self, base_command=command, alias=alias)
        if ru_info["model"] == "AHFII":
            cmd = (
                'docker exec -it {pid} bash -c "ssh -o UserKnownHostsFile=/dev/null -o StrictHostKeyChecking=no -o '
                'HostKeyAlgorithms=+ssh-rsa serviceuser@{ru_ip}"'.format(
                    pid=ru_info["pid"], ru_ip=ru_info["rf_ip"]
                )
            )
            logger.info(cmd)
            old_prompt = self.ssh_conn.get_prompt(alias=alias)
            new_prompt = "password:"
            self.ssh_conn.set_prompt(prompt_str=new_prompt, alias=alias)
            self.ssh_conn.execute(command=cmd, check_result=False, alias=alias)
            new_prompt = old_prompt + "|\\$|" + ru_prompt
            self.ssh_conn.set_prompt(prompt_str=new_prompt, alias=alias)
            logger.info(ru_info["password"])
            self.ssh_conn.execute(
                command=ru_info["password"], check_result=False, alias=alias
            )
        else:
            old_prompt = self.ssh_conn.get_prompt(alias=alias)
            new_prompt = old_prompt + "|" + ru_prompt
            self.ssh_conn.set_prompt(prompt_str=new_prompt, alias=alias)
            cmd = (
                'docker exec -it {pid} bash -c "ssh -o UserKnownHostsFile=/dev/null -o StrictHostKeyChecking=no -o '
                'HostKeyAlgorithms=+ssh-rsa root@{ru_ip}"'.format(
                    pid=ru_info["pid"], ru_ip=ru_info["rf_ip"]
                )
            )
            logger.console(cmd)
            self.ssh_conn.execute(command=cmd, check_result=False, alias=alias)
        cmd = "hostname"
        self.ssh_conn.execute(command=cmd, check_result=False, alias=alias)
        return alias

    def check_power_fdd(
        self, gnb_index, vdu_index, fhgw_index, ru_index, atten_list, alias="default"
    ):
        for atten in atten_list:
            try:
                cmd = "sudo /usr/bin/dapd -pwr {atten}".format(atten=atten)
                output = SSHConnExec.execute_normal_cmd(
                    self, base_command=cmd, alias=alias, check_result=False
                )
                if "sudo: not found" in output:
                    cmd = "/usr/bin/dapd -pwr {atten}".format(atten=atten)
                    output = SSHConnExec.execute_normal_cmd(
                        self, base_command=cmd, alias=alias, check_result=False
                    )
            except Exception as e:
                logger.info(e)
                cmd = "/usr/bin/dapd -pwr {atten}".format(atten=atten)
                output = SSHConnExec.execute_normal_cmd(
                    self, base_command=cmd, alias=alias, check_result=False
                )
            matches = re.search(r"TX=((-?\d+)(\.\d+).*FB=(-?\d+)(\.\d+))", output)
            if matches:
                logger.console(
                    "Power detected on CU_{gnb_index}_vdu_{vdu_index}_fhgw_{fhgw_index}_"
                    "ru_{ru_index}_att_{atten}:{result}".format(
                        gnb_index=gnb_index,
                        vdu_index=vdu_index,
                        fhgw_index=fhgw_index,
                        ru_index=ru_index,
                        atten=atten,
                        result=matches.group(),
                    )
                )
            else:
                logger.console("{output}".format(output=output))
                raise AssertionError(
                    "No power detected on CU_{gnb_index}_vdu_{vdu_index}_fhgw_{fhgw_index}_"
                    "ru_{ru_index}_att_{atten}".format(
                        gnb_index=gnb_index,
                        vdu_index=vdu_index,
                        fhgw_index=fhgw_index,
                        ru_index=ru_index,
                        atten=atten,
                    )
                )

    def collect_log_fdd(self, log_name, alias="default"):
        cmd = "log -a -z {log_name}".format(log_name=log_name)
        SSHConnExec.execute_normal_cmd(self, base_command=cmd, alias=alias)
        SSHConnExec.execute_normal_cmd(self, base_command="exit", alias=alias)

    def download_file_from_ru_fdd(
        self, pid, ru_ip, ruproxy_index, local_dir, log_name, alias="default"
    ):
        scp_command = (
            "docker exec -it {pid} bash -c "
            '"scp -o UserKnownHostsFile=/dev/null -o StrictHostKeyChecking=no -o HostKeyAlgorithms=+ssh-rsa '
            'root@{ru_ip}:/run/{log_name} /var/log/{log_name}"'.format(
                pid=pid, ru_ip=ru_ip, log_name=log_name
            )
        )

        logger.console(scp_command)
        SSHConnExec.execute_normal_cmd(self, base_command=scp_command, alias=alias)
        remote_path = "/var/log/RUOAM/ruproxy-{ruproxy_index}/log/{log_name}".format(
            ruproxy_index=ruproxy_index, log_name=log_name
        )
        local_path = "{local_dir}/{log_name}".format(
            log_name=log_name, local_dir=local_dir
        )
        self.ssh_conn.download_file(
            remote_path=remote_path, local_path=local_path, alias=alias
        )

    def disconnect_from_ru(self, alias="default"):
        SSHConnExec.disconnect_fhgw_ssh_conn(self, alias=alias)


class DCFDDRUOpe(SSHConnExec):
    def connect_to_ru_fdd_dc(
        self,
        ru_ip,
        username,
        password,
        ru_local_ip,
        ru_prompt="Node\\d:~#",
        alias="default",
        need_login_local_ip=True,
    ):
        old_prompt = self.ssh_conn.get_prompt(alias=alias)
        new_prompt = old_prompt + "|\\$|" + ru_prompt + "|:~#"
        cmd = "ssh -oHostKeyAlgorithms=+ssh-rsa -o StrictHostKeyChecking=no  {username}@{ru_ip}".format(
            username=username, ru_ip=ru_ip
        )
        self.ssh_conn.set_prompt(prompt_str=new_prompt, alias=alias)
        self.ssh_conn.execute(command=cmd, check_result=False, alias=alias)
        if need_login_local_ip is True:
            cmd = "ssh {ru_local_ip}".format(ru_local_ip=ru_local_ip)
            self.ssh_conn.execute(command=cmd, check_result=False, alias=alias)
            time.sleep(1)
        return alias

    def check_power_dc_fdd(self, atten, alias="default"):
        try:
            cmd = "sudo dapd -pwr {atten}".format(atten=atten)
            output = SSHConnExec.execute_normal_cmd(
                self, base_command=cmd, alias=alias, check_result=False
            )
            if "sudo: not found" in output:
                cmd = "dapd -pwr {atten}".format(atten=atten)
                output = SSHConnExec.execute_normal_cmd(
                    self, base_command=cmd, alias=alias, check_result=False
                )
        except Exception as e:
            logger.info(e)
            cmd = "dapd -pwr {atten}".format(atten=atten)
            output = SSHConnExec.execute_normal_cmd(
                self, base_command=cmd, alias=alias, check_result=False
            )
        matches = re.search(r"TX=((-?\d+)(\.\d+).*FB=(-?\d+)(\.\d+))", output)
        if matches:
            logger.console(
                "Power detected on att_{atten}:{result}".format(
                    atten=atten, result=matches.group()
                )
            )
        else:
            logger.console("{output}".format(output=output))
            raise AssertionError(
                "No power detected on _att_{atten}".format(atten=atten)
            )

    def exit_from_dc_fdd_ru(self, alias="default"):
        self.ssh_conn.execute("exit", alias=alias, check_result=False)
